  1	import type { IncomingMessage, ServerResponse } from 'node:http';
  2	import type { Router } from '../router.js';
  3	import type { AppConfig } from '../../config/config.types.js';
  4	import type { PollingManager } from '../pollingManager.js';
  5	import { saveConfigField } from '../../config/config.js';
  6	import { parseJsonBody, sendJson, sendError, isPlainObject } from '../requestUtils.js';
  7	
  8	// Polling-interval bounds — shared with settings UI (gui/public/js/views/settings.js).
  9	import {
 10	    MIN_POLLING_INTERVAL_SECONDS,
 11	    MAX_POLLING_INTERVAL_SECONDS,
 12	    MIN_NOTES_CARD_HEIGHT,
 13	    MAX_NOTES_CARD_HEIGHT,
 14	    MIN_NOTES_COLUMNS,
 15	    MAX_NOTES_COLUMNS,
 16	} from '../../config/config.constants.js';
 17	
 18	// ---------------------------------------------------------------------------
 19	// Helpers
 20	// ---------------------------------------------------------------------------
 21	
 22	/**
 23	 * Masks a credential token for display in API responses.
 24	 * Shows the last 4 characters of the token prefixed with `****`.
 25	 * Tokens shorter than 4 characters are fully masked as `****`.
 26	 */
 27	function maskToken(token: string): string {
 28	    return token.length < 4 ? '****' : '****' + token.slice(-4);
 29	}
 30	
 31	/**
 32	 * Extracts and lowercases the scheme from a URL string (the part before the
 33	 * first `:`). Returns an empty string when no colon is present.
 34	 *
 35	 * @example extractScheme('https://example.com') // → 'https'
 36	 * @example extractScheme('javascript:alert(1)') // → 'javascript'
 37	 */
 38	function extractScheme(url: string): string {
 39	    const colonIdx = url.indexOf(':');
 40	    return colonIdx !== -1 ? url.slice(0, colonIdx).toLowerCase() : '';
 41	}
 42	
 43	/**
 44	 * Type guard that returns `true` when `value` is a finite integer number.
 45	 * Used by PUT route handlers to validate numeric config fields.
 46	 */
 47	function isValidFiniteInteger(value: unknown): value is number {
 48	    return typeof value === 'number' && Number.isFinite(value) && Number.isInteger(value);
 49	}
 50	
 51	/**
 52	 * Returns a copy of the credentials map with all tokens masked.
 53	 */
 54	function buildMaskedCredentials(
 55	    credentials: Record<string, string> | undefined,
 56	): Record<string, string> {
 57	    if (!credentials) return {};
 58	    const masked: Record<string, string> = {};
 59	    for (const [host, token] of Object.entries(credentials)) {
 60	        masked[host] = maskToken(token);
 61	    }
 62	    return masked;
 63	}
 64	
 65	// ---------------------------------------------------------------------------
 66	// Route registration
 67	// ---------------------------------------------------------------------------
 68	
 69	// ---------------------------------------------------------------------------
 70	// Named-options interface
 71	// ---------------------------------------------------------------------------
 72	
 73	export interface ConfigRoutesOptions {
 74	    router: Router;
 75	    appConfig: AppConfig;
 76	    /** Optional absolute path to `config.json`. Defaults to the tool-root `config.json`. */
 77	    configPath?: string;
 78	    /** Optional `PollingManager`. When provided, PUT /api/config/polling restarts the loop. */
 79	    pollingManager?: PollingManager;
 80	}
 81	
 82	/**
 83	 * Registers REST endpoints for managing application configuration in
 84	 * `config.json`.
 85	 *
 86	 * **Credentials endpoints:**
 87	 *
 88	 * | Method | Path                              | Description               |
 89	 * |--------|-----------------------------------|---------------------------|
 90	 * | GET    | /api/config/credentials           | List credentials (masked) |
 91	 * | PUT    | /api/config/credentials           | Add / update an entry     |
 92	 * | DELETE | /api/config/credentials/:host     | Remove an entry           |
 93	 *
 94	 * **Polling endpoints:**
 95	 *
 96	 * | Method | Path                    | Description                                          |
 97	 * |--------|-------------------------|------------------------------------------------------|
 98	 * | GET    | /api/config/polling     | Return current `gitPollingIntervalSeconds`           |
 99	 * | PUT    | /api/config/polling     | Update the polling interval (min 10 s, max 86400 s)  |
100	 *

101	 * **Webserver URL endpoints:**
102	 *
103	 * | Method | Path                         | Description                              |
104	 * |--------|------------------------------|------------------------------------------|
105	 * | GET    | /api/config/webserver-url    | Return current `webserverUrl` (or null)  |
106	 * | PUT    | /api/config/webserver-url    | Update the webserver URL                 |
107	 *
108	 * **Notes display endpoints:**
109	 *
110	 * | Method | Path                          | Description                                                                                                         |
111	 * |--------|-------------------------------|---------------------------------------------------------------------------------------------------------------------|
112	 * | GET    | /api/config/notes-display     | Return current `notesCardHeight` and `notesColumns`                                                                 |
113	 * | PUT    | /api/config/notes-display     | Update notes display settings (partial updates — all fields optional). Fields: `notesCardHeight` ∈ [120, 800] (integer px), `notesColumns` ∈ [1, 6] (integer) |
114	 *
115	 * Changes take effect immediately (the in-memory `appConfig` is mutated) and
116	 * are persisted to `config.json` via `saveConfigField()`.
117	 *
118	 * **Security:** tokens are never returned in full — only the last 4 characters
119	 * are exposed. The `host` field is validated against an injection-safe pattern.
120	 *
121	 * @param options - Named-options bag: `router`, `appConfig`, optional
122	 *   `configPath` (defaults to tool-root `config.json`), optional
123	 *   `pollingManager` (restarts polling loop when present).
124	 */
125	export function registerConfigRoutes(options: ConfigRoutesOptions): void {
126	    const { router, appConfig, configPath, pollingManager } = options;
127	    // ------------------------------------------------------------------
128	    // GET /api/config/credentials — list all (tokens masked)
129	    // ------------------------------------------------------------------
130	    router.get('/api/config/credentials', (
131	        _req: IncomingMessage,
132	        res: ServerResponse,
133	        _params: Record<string, string>,
134	    ): void => {
135	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
136	    });
137	
138	    // ------------------------------------------------------------------
139	    // PUT /api/config/credentials — add or update a single entry
140	    // ------------------------------------------------------------------
141	    router.put('/api/config/credentials', async (
142	        req: IncomingMessage,
143	        res: ServerResponse,
144	        _params: Record<string, string>,
145	    ): Promise<void> => {
146	        let body: unknown;
147	        try {
148	            body = await parseJsonBody(req);
149	        } catch (err) {
150	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
151	            return;
152	        }
153	
154	        if (!isPlainObject(body)) {
155	            sendError(res, 400, 'Request body must be a JSON object.');
156	            return;
157	        }
158	
159	        const { host, token } = body as { host?: unknown; token?: unknown };
160	
161	        if (typeof host !== 'string' || host.trim() === '') {
162	            sendError(res, 400, 'Missing or invalid field "host": must be a non-empty string.');
163	            return;
164	        }
165	
166	        if (typeof token !== 'string' || token.trim() === '') {
167	            sendError(res, 400, 'Missing or invalid field "token": must be a non-empty string.');
168	            return;
169	        }
170	
171	        const cleanHost = host.trim();
172	
173	        // Security: reject hosts with path separators or whitespace to prevent
174	        // key injection that could interfere with URL credential injection.
175	        if (/[\s/\\]/.test(cleanHost)) {
176	            sendError(res, 400, 'Field "host" must not contain path separators or whitespace.');
177	            return;
178	        }
179	
180	        // Defence-in-depth: reject prototype-pollution keys.
181	        if (['__proto__', 'constructor', 'prototype'].includes(cleanHost)) {
182	            sendError(res, 400, 'Field "host" contains a reserved name.');
183	            return;
184	        }
185	
186	        const cleanToken = token.trim();
187	
188	        // Update in-memory config.
189	        if (!appConfig.gitCredentials) {
190	            appConfig.gitCredentials = {};
191	        }
192	        appConfig.gitCredentials[cleanHost] = cleanToken;
193	
194	        // Persist to disk.
195	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
196	
197	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
198	    });
199	
200	    // ------------------------------------------------------------------
201	    // DELETE /api/config/credentials/:host — remove a single entry
202	    // Sync handler (no request body to parse — unlike the async PUT above).
203	    // ------------------------------------------------------------------
204	    router.delete('/api/config/credentials/:host', (
205	        _req: IncomingMessage,
206	        res: ServerResponse,
207	        params: Record<string, string>,
208	    ): void => {
209	        let host: string;
210	        try {
211	            host = decodeURIComponent(params['host']);
212	        } catch {
213	            sendError(res, 400, 'Malformed host parameter.');
214	            return;
215	        }
216	
217	        if (!appConfig.gitCredentials || !(host in appConfig.gitCredentials)) {
218	            sendError(res, 404, `No credential entry found for host "${host}".`);
219	            return;
220	        }
221	
222	        delete appConfig.gitCredentials[host];
223	
224	        // When the map is empty, remove the field entirely (undefined removes
225	        // it from config.json via saveConfigField).
226	        const isEmpty = Object.keys(appConfig.gitCredentials).length === 0;
227	        if (isEmpty) {
228	            appConfig.gitCredentials = undefined;
229	        }
230	
231	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
232	
233	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
234	    });
235	
236	    // ------------------------------------------------------------------
237	    // GET /api/config/polling — return the current polling interval
238	    // ------------------------------------------------------------------
239	    router.get('/api/config/polling', (
240	        _req: IncomingMessage,
241	        res: ServerResponse,
242	        _params: Record<string, string>,
243	    ): void => {
244	        sendJson(res, 200, {
245	            gitPollingIntervalSeconds: appConfig.gitPollingIntervalSeconds,
246	        });
247	    });
248	
249	    // ------------------------------------------------------------------
250	    // PUT /api/config/polling — update the polling interval
251	    // Validates: must be a finite integer >= 10.
252	    // ------------------------------------------------------------------
253	    router.put('/api/config/polling', async (
254	        req: IncomingMessage,
255	        res: ServerResponse,
256	        _params: Record<string, string>,
257	    ): Promise<void> => {
258	        let body: unknown;
259	        try {
260	            body = await parseJsonBody(req);
261	        } catch (err) {
262	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
263	            return;
264	        }
265	
266	        if (!isPlainObject(body)) {
267	            sendError(res, 400, 'Request body must be a JSON object.');
268	            return;
269	        }
270	
271	        const { seconds } = body as { seconds?: unknown };
272	
273	        if (!isValidFiniteInteger(seconds)) {
274	            sendError(res, 400, 'Missing or invalid field "seconds": must be a finite integer.');
275	            return;
276	        }
277	
278	        if (seconds < MIN_POLLING_INTERVAL_SECONDS) {
279	            sendError(
280	                res,
281	                400,
282	                `Field "seconds" must be at least ${MIN_POLLING_INTERVAL_SECONDS}. Received: ${seconds}.`,
283	            );
284	            return;
285	        }
286	
287	        if (seconds > MAX_POLLING_INTERVAL_SECONDS) {
288	            sendError(
289	                res,
290	                400,
291	                `Field "seconds" must be at most ${MAX_POLLING_INTERVAL_SECONDS} (24 hours). Received: ${seconds}.`,
292	            );
293	            return;
294	        }
295	
296	        // Update in-memory config.
297	        appConfig.gitPollingIntervalSeconds = seconds;
298	
299	        // Persist to disk.
300	        saveConfigField('gitPollingIntervalSeconds', seconds, configPath);

301	
302	        // Restart the polling loop with the new interval (if a manager was provided).
303	        if (pollingManager !== undefined) {
304	            pollingManager.restart(seconds);
305	        }
306	
307	        sendJson(res, 200, { gitPollingIntervalSeconds: appConfig.gitPollingIntervalSeconds });
308	    });
309	
310	    // ------------------------------------------------------------------
311	    // GET /api/config/webserver-url — return the current webserver URL
312	    // ------------------------------------------------------------------
313	    router.get('/api/config/webserver-url', (
314	        _req: IncomingMessage,
315	        res: ServerResponse,
316	        _params: Record<string, string>,
317	    ): void => {
318	        sendJson(res, 200, { webserverUrl: appConfig.webserverUrl ?? null });
319	    });
320	
321	    // ------------------------------------------------------------------
322	    // PUT /api/config/webserver-url — update the webserver URL
323	    // ------------------------------------------------------------------
324	    router.put('/api/config/webserver-url', async (
325	        req: IncomingMessage,
326	        res: ServerResponse,
327	        _params: Record<string, string>,
328	    ): Promise<void> => {
329	        let body: unknown;
330	        try {
331	            body = await parseJsonBody(req);
332	        } catch (err) {
333	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
334	            return;
335	        }
336	
337	        if (!isPlainObject(body)) {
338	            sendError(res, 400, 'Request body must be a JSON object.');
339	            return;
340	        }
341	
342	        const { url } = body as { url?: unknown };
343	
344	        if (typeof url !== 'string') {
345	            sendError(res, 400, 'Missing or invalid field "url": must be a string.');
346	            return;
347	        }
348	
349	        const trimmed = url.trim();
350	
351	        if (trimmed !== '') {
352	            // Defence-in-depth: reject dangerous URL schemes.
353	            const scheme = extractScheme(trimmed);
354	            if (['javascript', 'data', 'vbscript'].includes(scheme)) {
355	                sendError(res, 400, `URL scheme "${scheme}:" is not permitted.`);
356	                return;
357	            }
358	        }
359	
360	        // Strip trailing slashes to prevent double-slash in constructed URLs.
361	        const cleanUrl = trimmed !== '' ? trimmed.replace(/\/+$/, '') : undefined;
362	
363	        // Update in-memory config.
364	        appConfig.webserverUrl = cleanUrl;
365	
366	        // Persist to disk.
367	        saveConfigField('webserverUrl', cleanUrl, configPath);
368	
369	        sendJson(res, 200, { webserverUrl: appConfig.webserverUrl ?? null });
370	    });
371	
372	    // ------------------------------------------------------------------
373	    // GET /api/config/notes-display — return current notes display settings
374	    // ------------------------------------------------------------------
375	    router.get('/api/config/notes-display', (
376	        _req: IncomingMessage,
377	        res: ServerResponse,
378	        _params: Record<string, string>,
379	    ): void => {
380	        sendJson(res, 200, {
381	            notesCardHeight: appConfig.notesCardHeight,
382	            notesColumns: appConfig.notesColumns,
383	        });
384	    });
385	
386	    // ------------------------------------------------------------------
387	    // PUT /api/config/notes-display — update notes display settings
388	    // Accepts partial updates: only provided fields are modified.
389	    // Validates: notesCardHeight ∈ [MIN_NOTES_CARD_HEIGHT, MAX_NOTES_CARD_HEIGHT]
390	    //            notesColumns    ∈ [MIN_NOTES_COLUMNS,    MAX_NOTES_COLUMNS]
391	    // ------------------------------------------------------------------
392	    router.put('/api/config/notes-display', async (
393	        req: IncomingMessage,
394	        res: ServerResponse,
395	        _params: Record<string, string>,
396	    ): Promise<void> => {
397	        let body: unknown;
398	        try {
399	            body = await parseJsonBody(req);
400	        } catch (err) {
401	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
402	            return;
403	        }
404	
405	        if (!isPlainObject(body)) {
406	            sendError(res, 400, 'Request body must be a JSON object.');
407	            return;
408	        }
409	
410	        const { notesCardHeight, notesColumns } = body as {
411	            notesCardHeight?: unknown;
412	            notesColumns?: unknown;
413	        };
414	
415	        // Validate notesCardHeight if provided.
416	        if (notesCardHeight !== undefined) {
417	            if (!isValidFiniteInteger(notesCardHeight)) {
418	                sendError(res, 400, 'Field "notesCardHeight" must be a finite integer.');
419	                return;
420	            }
421	            if (notesCardHeight < MIN_NOTES_CARD_HEIGHT) {
422	                sendError(
423	                    res,
424	                    400,
425	                    `Field "notesCardHeight" must be at least ${MIN_NOTES_CARD_HEIGHT}. Received: ${notesCardHeight}.`,
426	                );
427	                return;
428	            }
429	            if (notesCardHeight > MAX_NOTES_CARD_HEIGHT) {
430	                sendError(
431	                    res,
432	                    400,
433	                    `Field "notesCardHeight" must be at most ${MAX_NOTES_CARD_HEIGHT}. Received: ${notesCardHeight}.`,
434	                );
435	                return;
436	            }
437	        }
438	
439	        // Validate notesColumns if provided.
440	        if (notesColumns !== undefined) {
441	            if (!isValidFiniteInteger(notesColumns)) {
442	                sendError(res, 400, 'Field "notesColumns" must be a finite integer.');
443	                return;
444	            }
445	            if (notesColumns < MIN_NOTES_COLUMNS) {
